import java.util.*;

class Solution {
  public int minimumTotal(List<List<Integer>> triangle) {
    int n = triangle.size();
    int[] dp = new int[n + 1];
    for (int row = n - 1; row >= 0; row--)
      for (int i = 0; i <= row; i++) dp[i] = Math.min(dp[i], dp[i + 1]) + triangle.get(row).get(i);
    return dp[0];
  }
}
